CREATE DATABASE IF NOT EXISTS visitor_photo_slideshow CHARACTER SET utf8mb4;
USE visitor_photo_slideshow;
CREATE TABLE IF NOT EXISTS visitors(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(12) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NULL,mobile VARCHAR(20) UNIQUE NULL,privacy_consent TINYINT(1) NOT NULL DEFAULT 0,display_consent TINYINT(1) NOT NULL DEFAULT 0,visits INT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS photos(id INT AUTO_INCREMENT PRIMARY KEY,visitor_id INT NOT NULL,filename VARCHAR(64) UNIQUE NOT NULL,original VARCHAR(255),status ENUM('pending','approved','rejected') DEFAULT 'pending',category VARCHAR(30) NOT NULL DEFAULT 'General',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(visitor_id) REFERENCES visitors(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS settings(k VARCHAR(50) PRIMARY KEY,v VARCHAR(100) NOT NULL);
INSERT IGNORE INTO settings VALUES('duration','5'),('order','chronological'),('auto_approve','0');
CREATE TABLE IF NOT EXISTS login_attempts(id INT AUTO_INCREMENT PRIMARY KEY,ip VARCHAR(45) NOT NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip));
